import React, {useEffect, useState} from 'react';
import {Table} from 'antd';
import './github.css'

const ProjectList = () => {
    const [data, setData] = useState([]);

    useEffect(() => {
        fetch('/github/github_trend.json')
            .then((response) => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then((jsonData) => {
                setData(jsonData);
            })
            .catch((error) => {
                console.error('Error fetching data:', error);
            });
    }, []);

    const columns = [
        {
            title: 'Repository',
            dataIndex: 'repo',
            key: 'repo',
            width: 200, // 设置列宽
            render: (text: string) => {
                return (<a href={'https://github.com/' + text} target={'_blank'}>{text}</a>)
            }
        },
        {
            title: 'Stars',
            dataIndex: 'stars',
            key: 'stars',
        },
        {
            title: 'WeekStar',
            dataIndex: 'week_star',
            key: 'week_star',
        },
        {
            title: 'MonthStar',
            dataIndex: 'month_star',
            key: 'month_star',
        },
        {
            title: 'SeasonStar',
            dataIndex: 'season_star',
            key: 'season_star',
        },
        {
            title: 'YearStar',
            dataIndex: 'year_star',
            key: 'year_star',
        },
    ];

    return (
        <div>
            <h1>Github Trend</h1>
            <Table dataSource={data} columns={columns} rowKey="repo" pagination={{pageSize: 20}}/>
        </div>
    );
};

export default ProjectList;