import React, { useEffect, useState } from 'react';
import { marked } from 'marked';
import Prism from 'prismjs';
import 'prismjs/themes/prism.css';
import { Button, message } from 'antd';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import './markdownRenderer.css';

interface MarkdownRendererProps {
  markdownText: string;
}

const getBackgroundColorByLevel = (level: number): string => {
  const colors = [
    '#FFEB3B', '#FFCA28', '#FFC107', '#FFA000', '#FF8F00', '#FF6F00'
  ];
  return colors[level - 1] || colors[colors.length - 1];
};

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ markdownText }) => {
  const [transformedHTML, setTransformedHTML] = useState<string>('');

  useEffect(() => {
    Prism.highlightAll();
  }, [transformedHTML]);

  useEffect(() => {
    const renderMarkdown = async () => {
      const renderedHTML = await marked(markdownText); // 确保这是一个字符串
      const newTransformedHTML = setBackgroundColor(renderedHTML);
      setTransformedHTML(newTransformedHTML);
    };

    renderMarkdown();
  }, [markdownText]);

  const setBackgroundColor = (html: string) => {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    doc.querySelectorAll('h1, h2, h3, h4, h5, h6').forEach((heading) => {
      const level = parseInt(heading.tagName[1], 10);
      const backgroundColor = getBackgroundColorByLevel(level);

      const container = document.createElement('div');
      container.style.backgroundColor = backgroundColor;
      container.style.padding = '10px';
      container.style.marginBottom = '10px';

      const clonedHeading = heading.cloneNode(true) as HTMLElement;
      container.appendChild(clonedHeading);

      let sibling: ChildNode | null = heading.nextSibling;
      while (sibling) {
        if (sibling instanceof Element && sibling.tagName.match(/^H[1-6]$/)) {
          break;
        }
        container.appendChild(sibling);
        sibling = sibling.nextSibling;
      }

      heading.parentNode?.removeChild(heading);
      heading.parentNode?.insertBefore(container, heading);
    });

    return doc.body.innerHTML;
  };

  return (
    <div className="markdown-renderer">
      {transformedHTML.split('<pre>').map((part, index) => {
        if (index === 0) {
          return <span key={index} dangerouslySetInnerHTML={{ __html: part }} />;
        }

        const [codeBlock, ...rest] = part.split('</pre>');
        return (
        <div key={index} style={{position: 'relative', marginBottom: '10px'}}>
          <CopyToClipboard text={codeBlock} onCopy={() => message.success('代码已复制到剪贴板！')}>
              <Button className="copy-button" type="primary" style={{
                width: 35,
                height: 20,
                position: 'absolute',
                top: '0px',
                right: '0px',
              }}>复制</Button>
            </CopyToClipboard>
            <pre dangerouslySetInnerHTML={{ __html: codeBlock }} />
            {rest.length > 0 && <span dangerouslySetInnerHTML={{ __html: rest.join('</pre>') }} />}
          </div>
        );
      })}
    </div>
  );
};

export default MarkdownRenderer;